-- +goose Up
-- Serve: teams (each with the leader who receives requests) and requests.
CREATE TABLE IF NOT EXISTS serve_teams (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    icon TEXT NOT NULL DEFAULT 'groups',
    leader_name TEXT NOT NULL DEFAULT '',
    leader_email TEXT NOT NULL DEFAULT '',
    leader_phone TEXT NOT NULL DEFAULT '',
    sort_order INTEGER NOT NULL DEFAULT 0,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS serve_requests (
    id TEXT PRIMARY KEY,
    team_id TEXT NOT NULL REFERENCES serve_teams(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    phone TEXT NOT NULL DEFAULT '',
    availability TEXT NOT NULL DEFAULT '',
    message TEXT NOT NULL DEFAULT '',
    status TEXT NOT NULL DEFAULT 'new',
    emailed BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_serve_requests_created ON serve_requests(created_at DESC);

-- Attendance taken at the gate by scanning members' codes.
CREATE TABLE IF NOT EXISTS attendance (
    id TEXT PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    occasion TEXT NOT NULL,
    occasion_date DATE NOT NULL,
    event_id TEXT NOT NULL DEFAULT '',
    method TEXT NOT NULL DEFAULT 'qr',
    checked_in_by UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (user_id, occasion, occasion_date)
);
CREATE INDEX IF NOT EXISTS idx_attendance_date ON attendance(occasion_date DESC, occasion);

-- When each member started a reading plan (day 1), so "today" is known.
CREATE TABLE IF NOT EXISTS reading_plan_enrollments (
    plan_id TEXT NOT NULL REFERENCES reading_plans(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    started_on DATE NOT NULL DEFAULT CURRENT_DATE,
    PRIMARY KEY (plan_id, user_id)
);


